        } else {
            self.provider_path(models_dir)
        }
    }

    pub fn url(&self) -> String {
        if let Some(base) = self.base_url {
            return format!("{base}/{}", self.file);
        }
        match self.engine {
            Engine::Whisper => format!("{WHISPER_BASE_URL}/{}", self.file),
