//! Loader: read a catalog from a directory (working copy) or the bundled
//! shipped defaults, and expose the accessors and path/url helpers the old
//! `SpeechModel` methods provided.
//!
//! The three JSON files live in the crate root and are bundled via
//! `include_str!` as the shipped defaults.

use std::path::{Path, PathBuf};

use crate::CatalogError;
use crate::engine::Engine;
use crate::schema::Catalog;

pub const WHISPER_BASE_URL: &str = "https://huggingface.co/ggerganov/whisper.cpp/resolve/main";
pub const PARAKEET_BASE_URL: &str = "https://huggingface.co/ggml-org/parakeet-GGUF/resolve/main";
pub const FLUID_REPO_BASE_URL: &str = "https://huggingface.co";
pub const SHERPA_MODELS_BASE_URL: &str =
    "https://github.com/k2-fsa/sherpa-onnx/releases/download/asr-models";

impl Catalog {
    /// The shipped-default catalog, parsed from the three bundled JSON files
    /// and validated. Empty domains are valid (R2), so this does not panic
    /// before the data files are populated.
    pub fn bundled() -> Self {
        let speech: Vec<crate::schema::SpeechEntry> =
            serde_json::from_str(include_str!("../speech.json"))
                .expect("bundled speech.json is valid JSON");
        let llm: Vec<crate::schema::LlmEntry> =
            serde_json::from_str(include_str!("../llm.json"))
                .expect("bundled llm.json is valid JSON");
        let command: Vec<crate::schema::CommandEntry> =
            serde_json::from_str(include_str!("../command.json"))
                .expect("bundled command.json is valid JSON");
        let catalog = Catalog {
            speech,
            llm,
            command,
        };
        crate::validate::validate_catalog(&catalog).expect("bundled catalog passes validation");
        catalog
    }

    /// Load a catalog from a working-copy directory. Refuses to return a
    /// catalog if any file is missing or fails validation; the caller falls
    /// back to `bundled()` on error.
    pub fn load_from_dir(dir: &Path) -> Result<Catalog, CatalogError> {
        let read = |name: &str| -> Result<String, CatalogError> {
            std::fs::read_to_string(dir.join(name)).map_err(CatalogError::Io)
        };
        let speech: Vec<crate::schema::SpeechEntry> =
            serde_json::from_str(&read("speech.json")?).map_err(CatalogError::InvalidJson)?;
        let llm: Vec<crate::schema::LlmEntry> =
            serde_json::from_str(&read("llm.json")?).map_err(CatalogError::InvalidJson)?;
        let command: Vec<crate::schema::CommandEntry> =
            serde_json::from_str(&read("command.json")?).map_err(CatalogError::InvalidJson)?;
        let catalog = Catalog {
            speech,
            llm,
            command,
        };
        crate::validate::validate_catalog(&catalog)?;
        Ok(catalog)
    }

    pub fn speech(&self) -> &[crate::schema::SpeechEntry] {
        &self.speech
    }

    pub fn llm(&self) -> &[crate::schema::LlmEntry] {
        &self.llm
    }

    pub fn command(&self) -> &[crate::schema::CommandEntry] {
        &self.command
    }

    pub fn speech_by_id(&self, id: &str) -> Option<&crate::schema::SpeechEntry> {
        self.speech.iter().find(|e| e.id == id)
    }

    pub fn llm_by_id(&self, id: &str) -> Option<&crate::schema::LlmEntry> {
        self.llm.iter().find(|e| e.id == id)
    }

    pub fn command_by_id(&self, id: &str) -> Option<&crate::schema::CommandEntry> {
        self.command.iter().find(|e| e.id == id)
    }

    /// Whether the app may offer this speech model on `platform`: the host
    /// can load it, it is a dictation model rather than an auxiliary
    /// companion, the Core ML rows only exist when this build links the
    /// FluidAudio bridge, and this build compiled the engine that loads it.
    pub fn speech_offered_on(
        &self,
        entry: &crate::schema::SpeechEntry,
        platform: crate::engine::Platform,
        fluid_available: bool,
        parakeet_cpp_available: bool,
    ) -> bool {
        let engine = match Engine::from_name(&entry.engine) {
            Ok(e) => e,
            Err(_) => return false,
        };
        let transcribe_cpp_available =
            matches!(engine, Engine::TranscribeCpp) && platform.is_macos();
        engine.available_on(platform)
            && !entry.auxiliary
            && (engine != Engine::ParakeetCoreml || fluid_available)
            && engine.built_on(platform, parakeet_cpp_available, transcribe_cpp_available)
            && !(platform.is_macos() && engine == Engine::SherpaParakeet)
    }

    /// The path handed to the speech provider under `models_dir`.
    pub fn speech_provider_path(
        &self,
        entry: &crate::schema::SpeechEntry,
        models_dir: &Path,
    ) -> PathBuf {
        let engine = Engine::from_name(&entry.engine).unwrap_or(Engine::Whisper);
        let file = entry.artifacts.first().map(|a| a.file.as_str()).unwrap_or(&entry.id);
        match engine {
            Engine::ParakeetCoreml => models_dir.join("fluid"),
            Engine::SherpaParakeet => {
                models_dir.join("sherpa").join(sherpa_dir_name(file))
            }
            Engine::Qwen3Asr => models_dir.join(&entry.id),
            Engine::AppleSpeech => models_dir.join("apple-speech"),
            Engine::Whisper | Engine::Parakeet | Engine::ParakeetCpp | Engine::TranscribeCpp => {
                models_dir.join(file)
            }
            Engine::Onnx => models_dir.join(&entry.id),
        }
    }

    /// Where this model's bytes live under `models_dir`, used for installed
    /// / downloaded status. Differs from `speech_provider_path` only for the
    /// Core ML bridge, which receives the base directory.
    pub fn speech_install_path(
        &self,
        entry: &crate::schema::SpeechEntry,
        models_dir: &Path,
    ) -> PathBuf {
        let engine = Engine::from_name(&entry.engine).unwrap_or(Engine::Whisper);
        if engine == Engine::ParakeetCoreml {
            let file = entry
                .artifacts
                .first()
                .map(|a| a.file.as_str())
                .unwrap_or(&entry.id);
            models_dir.join("fluid").join(fluid_dir_name(file))
        } else {
            self.speech_provider_path(entry, models_dir)
        }
    }

    /// The download URL for this speech model's primary artifact.
    pub fn speech_url(&self, entry: &crate::schema::SpeechEntry) -> String {
        let file = match entry.artifacts.first() {
            Some(a) => a.file.as_str(),
            None => return String::new(),
        };
        if let Some(base) = &entry.base_url {
            return format!("{base}/{file}");
        }
        let engine = Engine::from_name(&entry.engine).unwrap_or(Engine::Whisper);
        match engine {
            Engine::Whisper => format!("{WHISPER_BASE_URL}/{file}"),
            Engine::Parakeet | Engine::ParakeetCpp => format!("{PARAKEET_BASE_URL}/{file}"),
            Engine::ParakeetCoreml => format!("{FLUID_REPO_BASE_URL}/FluidInference/{file}"),
            Engine::SherpaParakeet => format!("{SHERPA_MODELS_BASE_URL}/{file}"),
            Engine::Qwen3Asr | Engine::TranscribeCpp => {
                tracing::warn!(
                    "{:?} row has no base_url; returning an empty URL",
                    engine
                );
                String::new()
            }
            Engine::AppleSpeech => {
                tracing::warn!("apple speech rows are not downloadable; returning an empty URL");
                String::new()
            }
            Engine::Onnx => String::new(),
        }
    }
}

/// The directory a sherpa release archive extracts to: its file name without
/// the `.tar.bz2` suffix.
fn sherpa_dir_name(file: &str) -> &str {
    file.strip_suffix(".tar.bz2").unwrap_or(file)
}

/// The cache folder FluidAudio uses for a Core ML repo slug.
fn fluid_dir_name(file: &str) -> &str {
    match file {
        "parakeet-ctc-110m-coreml" | "parakeet-ctc-0.6b-coreml" => file,
        _ => file.strip_suffix("-coreml").unwrap_or(file),
    }
}

//! Validator: re-runs the invariants the existing catalog tests assert, now
//! against parsed data. One API used by both CI (build-time) and the update
//! path (runtime).
//!
//! R2: an empty slice is VALID for every domain. R4: the recommended rule is
//! "at least one" per non-empty speech/llm domain, no upper bound; command
//! is exempt.

use crate::CatalogError;
use crate::engine::Engine;
use crate::schema::{Catalog, CommandEntry, LlmEntry, SpeechEntry};

/// The chip vocabulary the UI may show. A label outside this list is a
/// catalog bug, not a wording choice.
const PURPOSE_LABELS: &[&str] = &[
    "Everyday dictation",
    "Fastest",
    "Most accurate",
    "Multilingual",
    "English only",
    "Live streaming",
    "Context-aware",
    "Low memory",
    "No download",
    "Long recordings",
    "Indian languages",
    "Experimental",
];

fn is_64_hex(s: &str) -> bool {
    s.len() == 64 && s.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f'))
}

fn check_ids<'a>(ids: impl Iterator<Item = &'a str>, domain: &str) -> Result<(), CatalogError> {
    use std::collections::HashSet;
    let mut seen = HashSet::new();
    for id in ids {
        if !seen.insert(id) {
            return Err(CatalogError::Validation(format!(
                "{domain}: duplicate id {id}"
            )));
        }
    }
    Ok(())
}

/// Invariant 7 (R7): `size_mb * 1_000_000 + 1024 >= sum(artifact bytes)`.
fn size_covers_artifacts(id: &str, size_mb: u32, total_bytes: u64) -> Result<(), CatalogError> {
    let budget = u64::from(size_mb).saturating_mul(1_000_000).saturating_add(1024);
    if budget < total_bytes {
        return Err(CatalogError::Validation(format!(
            "{id}: size_mb {size_mb} does not cover {total_bytes} artifact bytes"
        )));
    }
    Ok(())
}

fn check_runs_on(id: &str, runs_on: &[String]) -> Result<(), CatalogError> {
    if runs_on.is_empty() {
        return Err(CatalogError::Validation(format!("{id}: runs_on is empty")));
    }
    for p in runs_on {
        if !matches!(p.as_str(), "macos" | "windows" | "linux") {
            return Err(CatalogError::Validation(format!(
                "{id}: unknown platform in runs_on: {p}"
            )));
        }
    }
    Ok(())
}

fn check_artifact_hashes(id: &str, artifacts: &[crate::schema::Artifact]) -> Result<(), CatalogError> {
    for a in artifacts {
        if let Some(sha) = &a.sha256 {
            if !is_64_hex(sha) {
                return Err(CatalogError::Validation(format!(
                    "{id}: artifact {} sha256 is not 64 lowercase hex",
                    a.file
                )));
            }
        }
    }
    Ok(())
}

pub fn validate_speech(entries: &[SpeechEntry]) -> Result<(), CatalogError> {
    check_ids(entries.iter().map(|e| e.id.as_str()), "speech")?;
    if !entries.is_empty() && !entries.iter().any(|e| e.recommended) {
        return Err(CatalogError::Validation(
            "speech: no recommended row (R4: at least one required for a non-empty domain)".into(),
        ));
    }
    for e in entries {
        Engine::from_name(&e.engine).map_err(|_| {
            CatalogError::Validation(format!("speech {}: unknown engine {}", e.id, e.engine))
        })?;
        for p in &e.purposes {
            if !PURPOSE_LABELS.contains(&p.label.as_str()) {
                return Err(CatalogError::Validation(format!(
                    "speech {}: purpose label not in vocabulary: {}",
                    e.id, p.label
                )));
            }
        }
        // Invariant 5: sha256 may be absent only for the Core ML repo shape
        // (parakeet-coreml) and the OS-managed Apple-speech shape (empty
        // artifacts). Any other artifact must pin its hash.
        let engine = Engine::from_name(&e.engine).unwrap_or(Engine::Whisper);
        let sha_exempt = matches!(
            engine,
            Engine::ParakeetCoreml | Engine::AppleSpeech
        );
        if !sha_exempt {
            for a in &e.artifacts {
                if a.sha256.is_none() {
                    return Err(CatalogError::Validation(format!(
                        "speech {}: artifact {} has no sha256",
                        e.id, a.file
                    )));
                }
            }
        }
        check_artifact_hashes(&e.id, &e.artifacts)?;
        // Invariant 6: languages agree with english_only.
        if e.english_only {
            match &e.languages {
                Some(langs) if langs == &["en".to_string()] => {}
                _ => {
                    return Err(CatalogError::Validation(format!(
                        "speech {}: english_only row must list exactly [\"en\"]",
                        e.id
                    )))
                }
            }
        }
        // Invariant 7 (R7).
        let total: u64 = e.artifacts.iter().map(|a| a.bytes).sum();
        size_covers_artifacts(&e.id, e.size_mb, total)?;
        // Invariant 8.
        check_runs_on(&e.id, &e.runs_on)?;
    }
    Ok(())
}

pub fn validate_llm(entries: &[LlmEntry]) -> Result<(), CatalogError> {
    check_ids(entries.iter().map(|e| e.id.as_str()), "llm")?;
    if !entries.is_empty() && !entries.iter().any(|e| e.recommended) {
        return Err(CatalogError::Validation(
            "llm: no recommended row (R4: at least one required for a non-empty domain)".into(),
        ));
    }
    for e in entries {
        check_artifact_hashes(&e.id, &e.shards)?;
        let total: u64 = e.shards.iter().map(|a| a.bytes).sum();
        size_covers_artifacts(&e.id, e.size_mb, total)?;
        check_runs_on(&e.id, &e.runs_on)?;
    }
    Ok(())
}

pub fn validate_command(entries: &[CommandEntry]) -> Result<(), CatalogError> {
    check_ids(entries.iter().map(|e| e.id.as_str()), "command")?;
    // Command is exempt from the recommended rule (R4).
    for e in entries {
        if !e.capabilities.contains(&crate::schema::Capability::ToolCalling) {
            return Err(CatalogError::Validation(format!(
                "command {}: must carry the tool_calling capability",
                e.id
            )));
        }
        Engine::from_name(&e.engine).map_err(|_| {
            CatalogError::Validation(format!("command {}: unknown engine {}", e.id, e.engine))
        })?;
        check_artifact_hashes(&e.id, &e.shards)?;
        let total: u64 = e.shards.iter().map(|a| a.bytes).sum();
        size_covers_artifacts(&e.id, e.size_mb, total)?;
        check_runs_on(&e.id, &e.runs_on)?;
    }
    Ok(())
}

pub fn validate_catalog(catalog: &Catalog) -> Result<(), CatalogError> {
    validate_speech(&catalog.speech)?;
    validate_llm(&catalog.llm)?;
    validate_command(&catalog.command)?;
    Ok(())
}

