/**
 * Git-mutation guard for automated (non-TUI) pi sessions.
 *
 * Why: on 2026-10-27 a background `pi` worker, mid-task and watching its tests
 * fail, ran `git stash && cargo test` to get a "clean baseline". `git stash` is
 * repo-wide, so it stripped the tracked edits of every file in the shared
 * worktree, including ~4 600 lines of uncommitted human work and four other
 * concurrent workers' in-flight changes. Prose instructions ("workers must
 * never run git stash") did not prevent it, because the rule is far from the
 * point of temptation. This is the technical control.
 *
 * Gate: `ctx.mode !== "tui"`, i.e. json / rpc / print sessions, which is how
 * the Teletype lead dispatches workers. A human's interactive session is never
 * interfered with.
 *
 * Blocking is fail-safe by design, so this handler must never throw.
 */
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

const DESTRUCTIVE = [
	"stash",
	"checkout",
	"restore",
	"reset",
	"clean",
	"rebase",
	"switch",
	"commit",
	"push",
	"pull",
	"merge",
	"cherry-pick",
	"apply",
	"am",
];

const DESTRUCTIVE_FLAGS = /(?:^|\s)-(?:D|d|force|hard|delete)\b/;

const REASON =
	`Blocked: this is a non-interactive session sharing a worktree, and this git command can ` +
	`discard other people's uncommitted work (a pi worker ran \`git stash\` on 2026-10-27 and ` +
	`untracked 39 files; see .agents/brain/learnings/2026-10-27-pi-worker-git-stash-wiped-tree.md). ` +
	`Never change git state from a worker session. To compare against a baseline, read a copy: ` +
	`\`git show HEAD:<path> > /tmp/base.rs\` and diff against that file. Do not run the command again.`;

/** Split a shell command line into the argument lists of each `git ...` run. */
function gitRuns(command: string): string[][] {
	const runs: string[][] = [];
	const tokens = command.split(/[\s;&|()`\n\r]+/).filter(Boolean);
	let current: string[] | null = null;
	for (const t of tokens) {
		if (t === "git" || t.endsWith("/git")) {
			if (current) runs.push(current);
			current = [];
			continue;
		}
		if (current) current.push(t);
	}
	if (current) runs.push(current);
	return runs;
}

function dangerousGit(command: string): string | null {
	for (const run of gitRuns(command)) {
		if (run.length === 0) continue;
		const head = run.find((tok) => !tok.startsWith("-"));
		if (!head) continue;
		const bare = head.includes(":") ? head.split(":").pop()! : head;
		if (DESTRUCTIVE.includes(bare)) {
			// `git checkout --ours/--theirs` during a conflict resolution is a
			// forward-moving action, not a discard of unseen work.
			if (bare === "checkout" && run.some((t) => /^--(ours|theirs)$/.test(t))) continue;
			return `git ${bare}`;
		}
		if (bare === "branch" && DESTRUCTIVE_FLAGS.test(run.join(" "))) {
			return "git branch (delete)";
		}
	}
	return null;
}

export default function (pi: ExtensionAPI) {
	pi.on("tool_call", async (event, ctx) => {
		try {
			if (ctx.mode === "tui") return undefined;
			if (event.toolName !== "bash") return undefined;
			const command = (event.input as { command?: unknown }).command;
			if (typeof command !== "string") return undefined;
			if (dangerousGit(command)) {
				return { block: true, reason: REASON };
			}
			return undefined;
		} catch {
			return undefined;
		}
	});
}
